### Phase 4.2 — 阿里云 OSS 图片存储集成

#### 1. 新建 `backend/middleware/ossUpload.js`

```js
/**
 * ossUpload.js — 阿里云 OSS 上传中间件（渐进增强）
 * 若未配置 OSS_BUCKET，则降级为本地磁盘存储（现有逻辑）。
 *
 * 环境变量：
 *   OSS_BUCKET         阿里云 OSS Bucket 名称
 *   OSS_REGION         如 oss-cn-hangzhou
 *   OSS_ACCESS_KEY_ID  阿里云 AccessKeyId
 *   OSS_ACCESS_KEY_SECRET
 *   OSS_CDN_HOST       （可选）CDN 域名，如 https://cdn.alpinelink.com
 */
const path = require('path');
const crypto = require('crypto');

const OSS_ENABLED = !!(
  process.env.OSS_BUCKET &&
  process.env.OSS_REGION &&
  process.env.OSS_ACCESS_KEY_ID &&
  process.env.OSS_ACCESS_KEY_SECRET
);

let ossClient = null;

function getOssClient() {
  if (ossClient) return ossClient;
  try {
    const OSS = require('ali-oss');
    ossClient = new OSS({
      region: process.env.OSS_REGION,
      accessKeyId: process.env.OSS_ACCESS_KEY_ID,
      accessKeySecret: process.env.OSS_ACCESS_KEY_SECRET,
      bucket: process.env.OSS_BUCKET,
      secure: true,
    });
    return ossClient;
  } catch (e) {
    console.error('[OSS] ali-oss 未安装或初始化失败，降级为本地存储:', e.message);
    return null;
  }
}

/**
 * 上传 Buffer 到 OSS，返回公开访问 URL
 * @param {Buffer} buffer  文件内容
 * @param {string} originalname  原始文件名（用于获取扩展名）
 * @param {string} [folder='uploads']  OSS 路径前缀
 * @returns {Promise<string>}  公开 URL
 */
async function uploadToOss(buffer, originalname, folder = 'uploads') {
  const client = getOssClient();
  if (!client) throw new Error('OSS client not available');
  const ext = path.extname(originalname) || '.jpg';
  const key = `${folder}/${crypto.randomUUID()}${ext}`;
  await client.put(key, buffer);
  const cdnHost = process.env.OSS_CDN_HOST;
  if (cdnHost) return `${cdnHost.replace(/\/$/, '')}/${key}`;
  return `https://${process.env.OSS_BUCKET}.${process.env.OSS_REGION}.aliyuncs.com/${key}`;
}

/**
 * Express 中间件：将 req.file.buffer 上传到 OSS，
 * 并将 req.file.url 设为 OSS 公开 URL。
 * 若 OSS 未启用，直接 next()（降级本地存储）。
 */
async function ossUploadMiddleware(req, res, next) {
  if (!OSS_ENABLED) return next();
  if (!req.file && (!req.files || req.files.length === 0)) return next();
  try {
    const files = req.file ? [req.file] : req.files;
    for (const f of files) {
      if (!f.buffer && f.path) {
        const fs = require('fs');
        f.buffer = fs.readFileSync(f.path);
        try { fs.unlinkSync(f.path); } catch (e) {}
      }
      if (f.buffer) {
        f.ossUrl = await uploadToOss(f.buffer, f.originalname);
      }
    }
    next();
  } catch (e) {
    console.error('[OSS] 上传失败，降级本地存储:', e.message);
    next(); // 降级不阻断
  }
}

module.exports = { OSS_ENABLED, uploadToOss, ossUploadMiddleware };
```

#### 2. 更新 `backend/routes/upload.js`

在现有上传路由中，单张/多张图片上传成功后，若 `OSS_ENABLED` 为 true 且 `f.ossUrl` 存在，则将返回的 `url` 替换为 OSS URL：

在 `POST /` 路由的 `upload.single` 回调内，返回 url 时：
```js
const url = req.file.ossUrl || ('/uploads/' + req.file.filename);
```

在 `POST /multiple` 路由中：
```js
const urls = req.files.map(f => f.ossUrl || ('/uploads/' + f.filename));
```

在两个路由的 multer 配置前插入 `ossUploadMiddleware` 中间件（需要先 `const { ossUploadMiddleware, OSS_ENABLED } = require('../middleware/ossUpload');`）。

为支持 OSS buffer 模式，在 OSS 启用时将 multer storage 切换为 `multer.memoryStorage()`（只在 OSS_ENABLED 时）。具体在 upload.js 顶部：
```js
const { ossUploadMiddleware, OSS_ENABLED } = require('../middleware/ossUpload');
// 若 OSS 启用，使用内存存储（buffer）；否则使用磁盘存储
const activeStorage = OSS_ENABLED ? multer.memoryStorage() : storage;
const upload = multer({ storage: activeStorage, fileFilter: imageFilter, limits: { fileSize: 5 * 1024 * 1024 } });
```

#### 3. 在 `backend/package.json` 中将 `ali-oss` 设为可选依赖

在 `backend/package.json` 的 `optionalDependencies` 中添加：
```json
"ali-oss": "^6.20.0"
```

